1	#!/usr/bin/env node
2	
3	import readline from "node:readline/promises";
4	import { stdin as input, stdout as output } from "node:process";
5	import process from "node:process";
6	
7	import { AIMessage, HumanMessage } from "langchain/schema";
8	
9	import { createFraIAgentExecutor } from "../agent/executor.js";
10	
11	interface CliOptions {
12	  model?: string;
13	  verbose?: boolean;
14	  interactive?: boolean;
15	}
16	
17	interface ParsedArgs {
18	  options: CliOptions;
19	  input: string;
20	}
21	
22	const HELP_TEXT = `Usage: pnpm agent:frai "<instruction>"
23	
24	Options:
25	  --model <name>       Override the default OpenAI model (default: gpt-4o-mini)
26	  --interactive        Start an interactive REPL session
27	  --verbose            Log tool usage
28	  --help               Show this message
29	`;
30	
31	const parseArgs = (): ParsedArgs => {
32	  const raw = process.argv.slice(2);
33	  const options: CliOptions = {};
34	  const parts: string[] = [];
35	
36	  for (let index = 0; index < raw.length; index += 1) {
37	    const arg = raw[index];
38	    if (arg === "--help" || arg === "-h") {
39	      console.log(HELP_TEXT);
40	      process.exit(0);
41	    } else if (arg === "--model") {
42	      index += 1;
43	      options.model = raw[index];
44	    } else if (arg.startsWith("--model=")) {
45	      options.model = arg.split("=")[1];
46	    } else if (arg === "--interactive" || arg === "-i") {
47	      options.interactive = true;
48	    } else if (arg === "--verbose" || arg === "-v") {
49	      options.verbose = true;
50	    } else {
51	      parts.push(arg);
52	    }
53	  }
54	
55	  return {
56	    options,
57	    input: parts.join(" ").trim()
58	  };
59	};
60	
61	const logIntermediateSteps = (response: Record<string, unknown>) => {
62	  const steps = (response.intermediateSteps ?? []) as Array<{
63	    action?: { tool?: string; toolInput?: unknown };
64	    observation?: unknown;
65	  }>;
66	
67	  for (const step of steps) {
68	    if (step.action?.tool) {
69	      console.log(`→ Tool: ${step.action.tool}`);
70	      if (step.action.toolInput) {
71	        console.log(`  Input: ${JSON.stringify(step.action.toolInput)}`);
72	      }
73	    }
74	    if (step.observation) {
75	      console.log(`  Observation: ${typeof step.observation === "string" ? step.observation : JSON.stringify(step.observation)}`);
76	    }
77	  }
78	};
79	
80	const runSingleTurn = async (utterance: string, options: CliOptions) => {
81	  const executor = await createFraIAgentExecutor({
82	    model: options.model,
83	    verbose: options.verbose
84	  });
85	
86	  const response = (await executor.invoke({
87	    input: utterance,
88	    chat_history: []
89	  })) as Record<string, unknown>;
90	
91	  if (options.verbose) {
92	    logIntermediateSteps(response);
93	  }
94	
95	  if (typeof response.output === "string") {
96	    console.log(response.output);
97	  } else {
98	    console.log(JSON.stringify(response.output, null, 2));
99	  }
100	};
101	
102	const runInteractive = async (options: CliOptions) => {
103	  const executor = await createFraIAgentExecutor({
104	    model: options.model,
105	    verbose: options.verbose
106	  });
107	
108	  const rl = readline.createInterface({ input, output });
109	  const history: Array<AIMessage | HumanMessage> = [];
110	
111	  console.log("FRAI agent ready. Type `exit` to quit.");
112	
113	  while (true) {
114	    const message = (await rl.question("frai-agent> ")).trim();
115	    if (!message) continue;
116	    if (["exit", "quit", ":q"].includes(message.toLowerCase())) {
117	      break;
118	    }
119	
120	    const response = (await executor.invoke({
121	      input: message,
122	      chat_history: history
123	    })) as Record<string, unknown>;
124	
125	    history.push(new HumanMessage(message));
126	
127	    if (options.verbose) {
128	      logIntermediateSteps(response);
129	    }
130	
131	    const outputText =
132	      typeof response.output === "string"
133	        ? response.output
134	        : JSON.stringify(response.output, null, 2);
135	
136	    console.log(outputText);
137	    history.push(new AIMessage(outputText));
138	  }
139	
140	  rl.close();
141	};
142	
143	const main = async () => {
144	  const parsed = parseArgs();
145	  const hasInput = parsed.input.length > 0;
146	
147	  if (!hasInput) {
148	    await runInteractive({ ...parsed.options, interactive: true });
149	    return;
150	  }
151	
152	  await runSingleTurn(parsed.input, parsed.options);
153	};
154	
155	main().catch((error) => {
156	  console.error("FRAI agent encountered an error:", error instanceof Error ? error.message : error);
157	  process.exitCode = 1;
158	});
