export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  let anyThresholdsFailed = false;
  const metricsWithThresholds = evaluations.map((metric) => {
    const threshold = thresholds[metric.id];
    if (threshold !== undefined) {
      const passed = metric.score !== null && metric.score >= threshold;
      if (!passed) {
        anyThresholdsFailed = true;
      }
      return {
        ...metric,
        threshold,
        passed
      };
    }
    return metric;
  });

  return {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples,
      ...(Object.keys(thresholds).length > 0 && {
        thresholds,
        anyThresholdsFailed
      })
    },
    metrics: metricsWithThresholds
  };
}

