    referencesPath: dataset.referencesPath,
    ...(Object.keys(thresholds).length > 0 && { thresholds })
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (Object.keys(thresholds).length > 0) {
    console.log('\nThreshold Results:');
    report.metrics.forEach((metric: any) => {
      if (metric.passed !== undefined) {
        const status = metric.passed ? '✓ PASS' : '✗ FAIL';
        console.log(`  ${metric.id}: ${status} (threshold=${metric.threshold}, actual=${metric.score !== null ? metric.score.toFixed(4) : 'n/a'})`);
      }
    });
  }

  const exitCode = Object.keys(thresholds).length > 0 ? determineExitCode(report) : 0;
  process.exit(exitCode);
}

